    for i in range(1, n + 1):
        parts = lines[i].split()
        h.append(int(parts[0]))
        a.append(int(parts[1]))

    def ceil_div(a, b):
        return (a + b - 1) // b

    def verify(target):
        total_hammers = 0
        for i in range(n):
            final = h[i] + a[i] * m
            if final > target:
                needed = ceil_div(final - target, p)
                total_hammers += needed
                if total_hammers > k * m:
                    return False
        return True

    low = 0
    high = max(h[i] + a[i] * m for i in range(n))

    while low < high:
        mid = (low + high) // 2
        if verify(mid):
            high = mid
        else:
            low = mid + 1

    return str(low)

