def solution(input_str):
    import math
    from math import gcd
    import os

    # Generate the first 120 primes for flexibility
    primes = []
    num = 2
    while len(primes) < 120:
        is_prime = True
        for p in primes:
            if p * p > num:
                break
            if num % p == 0:
                is_prime = False
                break
        if is_prime:
            primes.append(num)
        num += 1
    primes.append(1)  # Include 1 as it's coprime to everything

    lines = input_str.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))

    b = []
    used_factors = set()

    for target in a:
        best_val = None
        best_diff = float('inf')

        # Try candidates near the target value first
        for offset in range(-5, 6):
            val = target + offset
            if val <= 0:
                continue
            if val in used_factors:
                continue

            # Check if all prime factors of val are compatible
            is_ok = True
            temp = val
            for p in primes:
                if p * p > temp:
                    break
                if temp % p == 0:
                    used_factors.add(p)
                    is_ok = False
                    break
            if is_ok:
                is_ok = True
                temp = val
                for p in primes:
                    if p * p > temp:
                        break
                    if temp % p == 0:
                        if p in used_factors:
                            is_ok = False
                            break
                        # Mark prime factor as used
                        used_factors.add(p)

                if is_ok:
                    diff = abs(target - val)
                    if diff < best_diff:
                        best_diff = diff
                        best_val = val

        if best_val is None:
            # Fallback: find any coprime value
            for val in primes:
                is_ok = True
                for bv in b:
                    if gcd(val, bv) != 1:
                        is_ok = False
                        break
                if is_ok:
                    diff = abs(target - val)
                    if diff < best_diff:
                        best_diff = diff
                        best_val = val
                    break

        b.append(best_val)
        # Remove used factors for next iteration
        used_factors = set()

    return ' '.join(map(str, b)) + '\n'

