def solution(input_string):
    parts = input_string.strip().split('\n')
    if len(parts) < 3:
        return 'NO\n'

    n = int(parts[0])
    k = int(parts[1])
    s = list(parts[2])

    @lru_cache(maxsize=None)
    def can_reach(pos, balance):
        if pos == n:
            return abs(balance) == k

        c = s[pos]

        for choice in ['W', 'L', 'D']:
            if c != '?' and c != choice:
                continue

            new_bal = balance + (1 if choice == 'W' else -1 if choice == 'L' else 0)

            # Check intermediate condition: |balance| < k
            if abs(new_bal) == k:
                continue

            if can_reach(pos + 1, new_bal):
                return True

        return False

    if not can_reach(0, 0):
        return 'NO\n'

    @lru_cache(maxsize=None)
    def reconstruct(pos, balance):
        if pos == n:
            return ''

        c = s[pos]

        for choice in ['W', 'L', 'D']:
            if c != '?' and c != choice:
                continue

            new_bal = balance + (1 if choice == 'W' else -1 if choice == 'L' else 0)

            # Check intermediate condition: |balance| < k
            if abs(new_bal) == k:
                continue

            rest = reconstruct(pos + 1, new_bal)
            if rest != 'NO':
                return choice + rest

        return 'NO'

    result = reconstruct(0, 0)
    if result == 'NO':
        return 'NO\n'
    return result + '\n'

